✅ Solution: Build a Login Page Using React

Here's a simple React login page with username and password inputs, state handling, and a basic submit handler.

```jsx
import React, { useState } from 'react';

function Login() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    // Simple validation example
    if (username === 'admin' && password === 'password') {
      setMessage('Login successful!');
    } else {
      setMessage('Invalid username or password');
    }
  };

  return (
    <div style={{ maxWidth: '300px', margin: 'auto', padding: '20px', border: '1px solid #ccc' }}>
      <h2>Login</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Username:</label><br />
          <input
            type="text"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', margin: '5px 0' }}
          />
        </div>
        <div>
          <label>Password:</label><br />
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ width: '100%', padding: '8px', margin: '5px 0' }}
          />
        </div>
        <button type="submit" style={{ padding: '10px', width: '100%', marginTop: '10px' }}>
          Login
        </button>
      </form>
      {message && <p style={{ marginTop: '10px' }}>{message}</p>}
    </div>
  );
}

export default Login;
```

### How to use:

1. Create a React app if you don't have one:
   ```bash
   npx create-react-app my-login-app
   cd my-login-app
   npm start
   ```

2. Save the above code in a file named `Login.js` inside the `src` folder.

3. Import and use the `Login` component in your `App.js`:

```jsx
import React from 'react';
import Login from './Login';

function App() {
  return (
    <div>
      <Login />
    </div>
  );
}

export default App;
```

### Next Steps:
- You can extend this by connecting to a backend API for real authentication.
- Add better styling using CSS or UI libraries like Material-UI or Bootstrap.
- Add form validation and error handling for a better user experience.

