      login(data.username); // Save user session on successful login
      // Redirect or update UI accordingly
    } else {
      setError(data.message || 'Login failed');
    }
  };

  // ...rest of component
}
```

3. **Set up protected routes using React Router:**

```jsx
// ProtectedRoute.js
import React, { useContext } from 'react';
import { Route, Redirect } from 'react-router-dom';
import { AuthContext } from './AuthContext';

function ProtectedRoute({ component: Component, ...rest }) {
  const { user } = useContext(AuthContext);

  return (
    <Route
      {...rest}
      render={(props) =>
        user ? <Component {...props} /> : <Redirect to="/login" />
      }
    />
  );
}

export default ProtectedRoute;
```

4. **Wrap your app with `AuthProvider` and use `ProtectedRoute`:**

```jsx
import React from 'react';
import { BrowserRouter as Router, Switch, Route } from 'react-router-dom';
import { AuthProvider } from './AuthContext';
import TruvoraLogin from './TruvoraLogin';
import Dashboard from './Dashboard'; // Example protected component
import ProtectedRoute from './ProtectedRoute';

function App() {
  return (
    <AuthProvider>
      <Router>
        <Switch>
          <Route path="/login" component={TruvoraLogin} />
          <ProtectedRoute path="/dashboard" component={Dashboard} />
          <Route path="/" exact>
            <Redirect to="/dashboard" />
          </Route>
        </Switch>
      </Router>
    </AuthProvider>
  );
}

export default App;
```

This setup ensures:

- User login state is saved in context and localStorage.
- Only authenticated users can access protected routes like `/dashboard`.
- Unauthenticated users are redirected to the login page.

